INSERT INTO public.bpei_assessment_questions(level,ordinal,domain,question,evaluator_answer) VALUES
(4,1,'Architecture','Quelle différence entre haute disponibilité et plan de reprise ?','La haute disponibilité réduit les interruptions ; le PRA rétablit après sinistre.'),
(4,2,'Architecture','Pourquoi rechercher les points uniques de défaillance ?','Une seule dépendance peut provoquer une panne de l''ensemble du service.'),
(4,3,'Réseau','Quels risques restent avec deux accès Internet ?','Routage, électricité, équipements ou prestataire peuvent rester des points communs.'),
(4,4,'Réseau','Comment investiguer une perte intermittente de paquets multisite ?','Mesurer par tronçon, corréler horaires et équipements puis vérifier les routes.'),
(4,5,'Sécurité','Comment conduire une revue des comptes à privilèges ?','Inventorier, vérifier besoin métier, propriétaires, durée et traçabilité.'),
(4,6,'Sécurité','Quelle réaction immédiate après fuite d''un secret API ?','Révoquer et remplacer, évaluer usages, contenir et investiguer l''incident.'),
(4,7,'Sécurité','Pourquoi séparer comptes admin et comptes bureautiques ?','Réduire exposition et utilisation habituelle des privilèges élevés.'),
(4,8,'Sécurité','Quelles étapes clés face à un ransomware ?','Isoler, préserver preuves, qualifier, coordonner, restaurer sainement et notifier.'),
(4,9,'Chiffrement','Pourquoi le chiffrement au repos ne suffit-il pas ?','Les sessions, accès applicatifs et clés peuvent aussi être compromis.'),
(4,10,'Cloud','Que protège une architecture multizone et que ne protège-t-elle pas ?','Elle limite certains incidents de zone mais pas une corruption logique globale.'),
(4,11,'Identité','Que vérifier face à un incident de connexion SSO ?','Fournisseur d''identité, certificats, claims, horloge, rôles et logs.'),
(4,12,'Observabilité','Différences entre logs, métriques et traces distribuées ?','Les logs décrivent événements, métriques quantifient, traces relient des appels.'),
(4,13,'Observabilité','Que signifient un SLO et un budget d''erreur ?','Un objectif mesuré de fiabilité et la quantité de défaillance tolérée.'),
(4,14,'Données','Comment concevoir la restauration d''une base PostgreSQL critique ?','Sauvegardes cohérentes, journaux WAL, chiffrement et exercices de restauration.'),
(4,15,'Données','Pourquoi choisir soigneusement le niveau d''isolation SQL ?','Il arbitre entre anomalies concurrentes évitées et performance des transactions.'),
(4,16,'Paiements','Pourquoi rendre un webhook de paiement idempotent ?','Empêcher un événement répété de créer un double encaissement logique.'),
(4,17,'Paiements','Comment sécuriser des paiements de marketplace ?','Identifier vendeur, KYC, responsabilités, clés, webhooks, litiges et rapprochement.'),
(4,18,'RGPD','Comment évaluer un transfert de données hors EEE ?','Inventorier, examiner mécanisme juridique, risques et garanties supplémentaires.'),
(4,19,'RGPD','Quand effectuer une analyse d''impact des données personnelles ?','Lorsque le traitement risque d''entraîner un risque élevé pour les droits.'),
(4,20,'Audit','Comment contrôler un fournisseur d''hébergement critique ?','Examiner clauses, certifications, accès, incidents, sauvegardes et réversibilité.'),
(4,21,'Mentorat','Comment superviser un Junior sans exposer les données client ?','Partager des cas anonymisés et limiter les accès au strict nécessaire.'),
(4,22,'Qualité','Quels indicateurs pertinents pour un réseau de techniciens ?','Résolution, retours, délai, réintervention, satisfaction et sécurité.'),
(4,23,'Qualité','Comment traiter une panne récurrente mal diagnostiquée ?','Conduire une analyse des causes racines et vérifier les corrections.'),
(4,24,'Décision','Quand un Master doit-il refuser une mission complexe ?','Lorsque compétence, sécurité, assurance, ressources ou délai sont insuffisants.'),
(4,25,'Évaluation','Comment valider une promotion Master objectivement ?','Associer cas pratiques, contrôle qualité, preuves techniques et décision motivée.');